import cmath, math
def v(t):
    D=4*t*(1-2*t)*(1-t); return -(t*t-3*t+1)**2/D
def pts(t):  # labelled points: 0:v,1:a0,2:a3,3:a2  (a1=inf)
    return [v(t),0.0+0j,t,1.0+0j]
r5=math.sqrt(5); r3=math.sqrt(3)
PUN={'0':0,'1':1,'h':0.5,'P1':(3-r5)/2,'P2':(3+r5)/2,'Q1':(-1+r5)/2,'Q2':(-1-r5)/2,'R-':0.5-1j*r3/6,'R+':0.5+1j*r3/6}
t0=0.3
H=2.0; eps=0.02
def path_for(name):
    p=PUN[name]
    if name=='R+':
        wp=[t0,t0+1j*H,p.real+1j*H,p+1j*eps]; start=p+1j*eps
    elif name=='h':
        wp=[t0,t0-1j*H,0.45-1j*H,0.45+0j,p-eps]; start=p-eps
    else:
        wp=[t0,t0-1j*H,p.real-1j*H,p-1j*eps]; start=p-1j*eps
    # segments
    seg=[]
    for a,b in zip(wp[:-1],wp[1:]):
        n=int(abs(b-a)/1e-4)+10
        seg+= [a+(b-a)*k/n for k in range(n)]
    th0=cmath.phase(start-p); n=20000
    circ=[p+eps*cmath.exp(1j*(th0+2*math.pi*k/n)) for k in range(n)]
    back=list(reversed(seg))
    return seg+circ+back+[t0]
def mindist(path):
    m=1e9
    for t in path:
        for q in PUN.values():
            m=min(m,abs(t-q))
    return m
def braid(path):
    # returns list of (k, sign) generators in slot positions, plus final permutation check
    P=pts(path[0]); order=sorted(range(4),key=lambda i:P[i].real)
    word=[]
    for t in path[1:]:
        P=pts(t)
        changed=True
        while changed:
            changed=False
            for k in range(3):
                i,j=order[k],order[k+1]
                if P[i].real>P[j].real:
