def refine(path):
    out=[path[0]]
    def ok(a,b):
        Pa,Pb=pts(a),pts(b)
        sep=min(abs(Pa[i]-Pa[j]) for i in range(4) for j in range(i))
        mv=max(abs(Pa[i]-Pb[i]) for i in range(4))
