# free group words: list of (gen, ±1), gens 0..3 = slots
def red(w):
    o=[]
    for x in w:
        if o and o[-1][0]==x[0] and o[-1][1]==-x[1]: o.pop()
        else: o.append(x)
    return o
def inv(w): return [(g,-e) for g,e in reversed(w)]
def gen_aut(k,s):
    # returns dict slot->word
    A={i:[(i,1)] for i in range(4)}
    if s==1:
        A[k]=[(k+1,1)]; A[k+1]=[(k+1,1),(k,1),(k+1,-1)]
    else:
        A[k+1]=[(k,1)]; A[k]=[(k,-1),(k+1,1),(k,1)]
    return A
def apply(A,w):
    o=[]
    for g,e in w:
        o+= A[g] if e==1 else inv(A[g])
