def evalw(rho,w,m):
    r=tuple(range(m))
    for g,e in w:
        r=pmul(r, rho[g] if e==1 else pinv(rho[g]))
    return r
def act(phi,rho,m):
    return tuple(evalw(rho,phi[i],m) for i in range(4))
def canon(rho,m):
    # canonical rep under simultaneous conjugation: relabel by BFS order from each start point
    best=None
    gens=rho
    for s in range(m):
        lab={s:0}; queue=[s]; k=0
        while k<len(queue):
            x=queue[k]; k+=1
            for g in gens:
                for y in (g[x],):
                    if y not in lab: lab[y]=len(lab); queue.append(y)
        if len(lab)<m: return None  # require transitive
        cand=tuple(tuple(lab[g[pinv_l]] for pinv_l in sorted(lab,key=lambda z:lab[z])) for g in gens)
